-- GENERATED by `wfj generate` from data/quest/quest-0086.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [86574] = { "Stonetalonへの補給便", "Pridewing WyvernからStonetalon Suppliesを$N1個集め、Innkeeper Faraliaに届ける。", "<ここにある不運な遺体には、Pridewingのwyvernに何度も襲われた跡がある。近くの荷物袋はしわくちゃになって打ち捨てられ、中身はなくなっている。失われたものを示すのは、運び屋の手に握られた小さなメモだけだ。Stonetalon PeakのInnkeeper Faralia宛ての荷物だった。>\n\n<wyvernたちは、巣に敷くために補給品の包みを持ち去ったのだろう。>", nil, nil, 0x91254c7f, 0x88cf623c, 0x25ddc985, nil, nil, "...mm" },
  [86576] = { "Bloodfuryの装身具", "Glittering Sunstoneを$N1個、Mor'rogalのところへ持って行ってください。", "Bloodfury harpiesは、Charred Vale一帯に汚物をまき散らすだけでなく、見つけた光り物を何でも集めている。奴らは飾りにするために、さまざまな黄金色のsunstonesを集めているそうだ。私にはそんな小物は用がないが、Mor'rogalが前にそれを使うと言っていた。\n\nValeのharpiesと戦う間、Glittering Sunstonesに目を光らせておいてくれ。見つけたものは、ここから上の丘にいるMor'rogalのところへ持っていくといい。", nil, nil, 0x8c0d1828, 0x3c6482c9, 0x2a34d371, nil, nil, "...mm" },
  [86577] = { "腐敗の標本", "Putrescent Bear Organsを$N1個とPutrescent Wolf Organsを$N2個、Kelek Skykeeperのところへ持って行ってください。", "Hyjalから降り注ぐ堕落は山の水を通して流れ、この森のあらゆるものに染み込んでいます。その水を飲んだ生き物たちは、堕落を体内に取り込んでしまうのです。それによって彼らは獰猛になり、病に冒され、恐れを知らなくなります。\n\nこうした影響に対抗するには、まずそれを理解しなければなりません。そのためには、冒された者たちのサンプルが必要です。\n\n狼や熊のputrescent organsのサンプルがいくつかあれば十分でしょう。急ぐ必要はありません。Felwoodにはそうした生き物がたくさんいますから。", nil, nil, 0xfedf93d7, 0xd851b48c, 0x23067a2e, nil, nil, "...mm" },
  [86585] = { "倒れた者たちの旗", "Ironforgeの旗を掲げてtroggのHeadsplitterをおびき出して倒し、Captain Rugelfussに報告してください。", "倒れた山岳兵は、Ironforgeの旗を持っている。偵察していたのか、それとも絶望的な突撃をしていたのか。いずれにせよ、旗は投げ捨てられ、踏みにじられている。この山岳兵は頭をひどく殴られて兜が吹き飛ばされ、その場で絶命していた。おそらくtroggが棘付きの棍棒でやったのだろう。\n\n彼女を殺したtroggは、おそらくまだ近くにいて、この旗を覚えているはずだ。Ironforgeの旗をもう一度掲げれば、それをおびき出せるかもしれない。", "その旗、まるで戦争をくぐり抜けてきたみたいだな！", "Ylvaの遺体を見つけたのか？ああ、気の毒に。あいつは、Ironforgeが決してtroggどもの手に落ちはしないと奴らに思い知らせてやると言っていた。troggの土地を巡回したまま戻らなかった数人の登山家を探しに行ったんだ。用心するには独立心が強すぎる女だった。これで何があったのか分かったよ。\n\n旗は私が持ち帰って、きれいにして飾っておく。あいつの武器は君が持っていくといい。troggとの戦いで君の役に立ちますように。", 0xe9fba8e6, 0x55701efb, 0x9ae4d6b9, 0xe66f0ce2, 0x0c4098ad, "....." },
  [86611] = { "Stag Lord's Bauble", "Stag Lord's Baubleを、それについて知っていそうなTalonbranch Gladeの誰かのところへ持って行ってください。", "<悪臭を放つ粘液の溜まりが、牡鹿の像を侵食している。どうやってこの湖の底にたどり着いたのかはわからない。\n\n首にかけられたメダリオンには水晶の石がひとつはめ込まれており、不健全な緑の輝きを放っている。この記念碑の歴史を知っていそうな誰かのところへ持っていく価値はあるだろう。>", nil, nil, 0x64f22cb2, 0xe8046376, 0x228be591, nil, nil, "...mm" },
  [86612] = { "Stag Lord's Bauble", "Stag Lord's Baubleを、それについて知っていそうなBloodvenom Postの誰かのところへ持って行ってください。", "<悪臭を放つ粘液の溜まりが、牡鹿の像を侵食している。どうやってこの湖の底にたどり着いたのかはわからない。\n\n首にかけられたメダリオンには水晶の石がひとつはめ込まれており、不健全な緑の輝きを放っている。この記念碑の歴史を知っていそうな誰かのところへ持っていく価値はあるだろう。>", nil, nil, 0x64f22cb2, 0xa5862f00, 0x228be591, nil, nil, "...mm" },
  [86613] = { "Excavation Tools", "Excavation Toolsを$N1個、Magmar Fellhewのところへ返してください。", "ドワーフたちがtroggから逃げた時に置き去りにされた発掘隊の道具は、ほとんど手つかずのようだ。発掘隊にこれを返せば、きっと作業の助けになるだろう。", "発掘現場をちょっと、その、調整するだけで、全部また軌道に戻せるんだ！", "俺たちの道具だ！\n\ntroggどもにキャンプを制圧されたとき、道具のほとんどを置いていくしかなかったんだ。この侵攻を食い止めて作業を再開できるようになったら、こいつは大助かりだよ！", 0x417702d1, 0x4b1ae3e2, 0xf80c3305, 0x5a718cf3, 0x5c97d609, "....." },
  [86614] = { "波の銀", "Monogrammed Silver Hair clipを持ち主に返す。", "<残骸の中の釣り道具のがらくたの中に、錆びた釣り針や壊れた釣り糸の糸巻き、それに「K.D.」の組み文字が入った、少し腐食してはいるが華やかな銀の髪留めがある>", "今日は雑用がたくさんあるから、手短に済ませてもらえるかい？", "私の髪留め！完全に失くしたと思ってたのに！\n\nちょっと手入れすればすぐにピカピカになるよ。届けてくれてありがとう！お礼はちゃんとするからね。", 0x90b2445c, 0x1d2fd811, 0xbaa09a33, 0x46c58e1a, 0x873f10f3, "....." },
  [86615] = { "条約の義務", "Wildhammer KeepでAmbassador Redstoneのなくなった外交用の鞄を見つけてください。", "ああ！Wildhammersへの大使を務めておるというのに、最新の外交文書の入った鞄をWildhammer Keepのどこかに置き忘れてしもうた。酒場に置いてきたに違いない……いや、蒸気タンクのそばでなくしたのかも……それとも上の階だったか？どうにも覚えておれん！\n\nあの書類がいるんじゃ！わしよりもこの砦に目が利くなら、なくしたわしの外交用の鞄を見つけられるか試してくれんか！", nil, nil, 0xfe6a2053, 0x0e2ffe00, 0x49bb9f55, nil, nil, "...mm" },
  [86616] = { "転用されたトーテム", "Vilebranch Totemを$N1個Maret Firetendのところへ持ち帰る。", "シャーマンとして元素と交わるうえで難しいのは、目的を異にするほかのシャーマンもいることだ。元素は我々が何のために動くかなど気にしない。ただ頼まれたとおりにするだけだ！\n\nJintha'alorのトロールもシャーマンの術を使う。奴らの妨害と襲撃は、ここにいる我々にとって絶えず悩みの種なのだ。\n\n奴らのVilebranch totemsを見つけて持ち帰ってくれ。その力を打ち消してやる。持ち歩いているものもあれば、祭壇の周りに結界として置いているものもある。", nil, nil, 0xc14dbfc0, 0xb97eb9f3, 0x53fd7512, nil, nil, "...mm" },
  [86620] = { "雛の救出", "Gryphon Master TalonaxeのためにLost Gryphon Eggを$N1個集める。", "ここには良いgryphonの血統がいるが、野生には無事に育たないおそれのある卵の巣がいつもいくつかある。gryphonの親が狼との戦いに負けたり、病気になったりすることもある。助けがなければ、雛は決して生き延びられない。\n\n幸い、我々にはこうしたはぐれた幼いものを育てて守る手立てがある。野生でlost eggsを見つけたら、私のところへ持ってきてくれ。", nil, nil, 0x6f8f332b, 0x533d5825, 0x45ebd2e3, nil, nil, "...mm" },
  [86667] = { "雪に閉ざされて", "Jar of SnowをLochの北西の岸にある家にいるNorric Lochthaneに届ける。", "私の昔の師匠、Norricが、小さなエレメンタルに妙な頼みを持たせてよこしたんだ。シャーマンの術に使うため、jar of snowが要るらしい! 何に使うのかはさっぱりだが、魔法に関しては彼のやり方に口を出すなと、ずっと前に学んだのさ。\n\n私はこの辺りのエレメンタルについて学ぶので忙しくて、手伝いに行けない。South Gate Passのトンネルの入口へ行ってくれ。あそこなら一年中雪がある。この陶器の壺に少しすくって、溶ける前に彼に届けてくれ。壺が冷たさを保ってくれるはずだ。", "ん？何の用だ？", "この瓶を私に？\n\n雪だ！Grenhildがやってくれた！頼んでいた雪を送ってくれたんだ！\n\nでも残念だな、本人が会いに来てくれるのを期待していたのに。\n\nまあ、とにかく、骨を折ってくれてありがとう。仕事の本当に助けになるよ。", 0x7219b30d, 0xf3253110, 0x938b1d88, 0x8793ff36, 0x36e8bcbb, "....." },
  [86746] = { "Legashiの脅威", "Ruins of EldarthにいるEkkalのために、Legashi Satyrを$N1体、Legashi Roguesを$N2体、Legashi Hellcallersを$N3体倒してください。", "我が民は苦しんでいる、{name}。\n\nLegashiのsatyrが我らの住処に攻め込み、多くのBlackmawを堕落させ、我らを盟友Timbermawから引き離した。奴らの襲撃を生き延びた者たちは、急ごしらえの野営地で身を寄せ合っている。さらに悪いことに、satyrの堕落はこの地に広がりつつあり、ただでさえ弱っている我が部族を脅かしている。\n\nLegashiはここから北東の廃墟に潜んでいる。奴らを倒すため、君の助けを求めねばならない。", nil, nil, 0x2073c18d, 0x86f32380, 0x2ede136f, nil, nil, "...mm" },
  [86747] = { "Legashiの角", nil, "君は確かに私に力を示してくれた、{name}。だが、我が部族の他の者たちはそう簡単には納得しない。そのためには、Legashiとの戦いを続けてもらう必要がある。\n\n倒したLegashiのsatyrの角を持ってきてくれ。君が持ってくる束の一つ一つが、Blackmawへの君の奉仕の証となるだろう。", nil, nil, 0x46439031, nil, 0xb1c3b2ab, nil, nil, ".m.mm" },
  [86752] = { "Rageroarへの報告", "UrsolanにいるGatekeeper Rageroarと話してください。", "satyrとの戦いでは、まだやるべきことがたくさんある、{name}。\n\nさらに力を貸してくれるなら、北にあるUrsolanの野営地でGatekeeper Rageroarと話してくれ。君の力をどこで最も活かせるか、彼が知っているだろう。Ursolanはここから北にある。", nil, nil, 0xdada9623, 0x3ea1e944, 0xb2d23b77, nil, nil, "...mm" },
  [86757] = { "オークの進軍を遅らせる", "Jagged Orc Swordsを$N1本とCurved Orc Daggersを$N2本、Shandrinaに届ける。", "オークが東の森を占拠し、今や斥候や兵卒どもが森じゅうに潜んでいる！我々がAshenvaleを動き回るのは、もう安全じゃない。\n\nオークを押し返し、森を確保しなければ。奴らの野営地の周辺に慎重に忍び寄って、斥候や兵卒を何人か仕留めることはできた。\n\nオークと戦い、奴らが使っているぎざぎざの剣と曲がったナイフを持ってきてくれ。奴らの武器は回収して作り直し、無駄にはしないつもりだ。", nil, nil, 0xa5ae3f5b, 0xef062d38, 0xf54c066d, nil, nil, "...mm" },
  [86758] = { "ナイフをひねる", "crocoliskのDaggerfangを見つけて倒し、Marekのナイフを持ち帰ってください。", "俺がcrocoliskに手を食いちぎられかけた話、したことあったっけか？ なんとかナイフを奴の顎にねじ込んで、大慌てで這い出したんだ。そのナイフはこの辺のどこかにあるはずなんだが、どうも見つからねえ。\n\nとにかく、あのcrocはたぶんまだ湖のほとりで狩りをしてる。あの獰猛な獣は始末したほうがいいだろうな。少なくとも他のハンターたちの安全のためにもな。\n\n俺はそいつをDaggerfangって呼ぶことにしてる。見かけたら、俺からの親しみを込めた「挨拶」をしてやってくれ！ で、「挨拶」ってのは「ぶっ刺せ」って意味だ。", "狩りの調子はどうだ？", "はっ！やったな！あの老いぼれcrocが報いを受ける日が来るとは思わなかったが、これで十分だ！\n\nああ、えっと……実はな、俺は別のナイフを手に入れなきゃならなかったんだが、そっちのやつはあんたに幸運をもたらすかもしれん。持っておいたらどうだ？", 0xe00ca7df, 0x0397565f, 0x466c095b, 0x023e1b29, 0x855b32ce, "....." },
  [86776] = { "炉のための材料", "Bronze Barを$N1個、Morhan Coppertongueのところへ持って行ってください。", "Thelsamarは住むにはいい所だが、Ironforgeにあるような便利なものは全部揃ってるわけじゃない。青銅がいつも足りなくなるんだ！ 道具ややかんや鍋を作り続けるには、もっと青銅が要るんだよ！\n\nお前さん、炉の扱いに少しは覚えがあるようだな。bronze barsを精錬してもらえないか？ たっぷり払うぞ！", "炉の火を絶やすわけにはいかないんだ！", "ああ、助かった！これで炉を燃やし続けられるはずだ。いつか、石炭を定期的に町へ運んでくる商人が来てくれるといいんだがな！", 0xd4a01b9a, 0x3fc9ca9a, 0x466409ef, 0xef5d24bd, 0xde5ced06, "....." },
  [86777] = { "Master Feardred", "Master Feardredを倒し、彼のアミュレットをKorsaのところへ持って行ってください。", "Azsharaを汚すsatyrは数多いが、Legashiほど恐ろしい者はいない。Varrox Bleakhoofに率いられ、奴らの野営地が北の半島に点在している。奴らは我らを住処から追い出した。遠からずUrsolanも略奪されるのではないかと恐れている。\n\n生き延びる望みを持つには、反撃しなければならない。\n\nVarroxの手下であるMaster Feardredが、南にある近くの野営地を監督している。ここからでも見えるはずだ。FeardredはVarroxの軍勢を弱めるための重要な標的だ。奴を倒し、その首飾りを持ってきてくれ。", nil, nil, 0x9f2c93c4, 0x97b4c61a, 0xf118a1c4, nil, nil, "...mm" },
  [86784] = { "枝と骨", "Dry Branchを$N1本集め、Eleanor Shackletonのところへ持って行ってください。", "私の仲間のEleanor Shackletonは、荒野を旅し、天候や怪物に負けずに生き抜くことを誇りにしている。彼女は今、ここからそう遠くない西の丘で野営していてね。以前彼女がくれた助言を覚えているよ。「薪が十分だと思ったら、その5倍集めなさい」ってね。\n\n時間があるなら、このかごに木を集めて彼女の野営地へ持っていってくれないか。旅する冒険者の暮らしについて、きっといくつか助言をくれるはずだ。", "我が火へようこそ、旅人よ。", "薪の追加ですか？いつでも歓迎ですよ。これでGladesの寒い夜も、この老いた骨を温めておけます。\n\n薪を集めるための負い紐は自分で持っていますから、その籠はあなたが持っていてください。", 0x9975c906, 0x1d5e65f3, 0xbc307d2c, 0x5adb408d, 0x33ffab6b, "....." },
  [86791] = { "行方不明のBlackmawの斥候", "Ursolanの東にあるLegashiの野営地の近くで、Blackmawの偵察隊を見つけてください。", "少し前、Legashiの拠点について情報を集め、できれば我らの族長を見つけるため、偵察隊を送り出した。まだ戻ってこない。最悪の事態を恐れ始めているところだ。\n\nLegashiはここから東に多くの野営地を持っている。偵察隊の誰かがまだ生きているなら、おそらくこの近くのどこかにいるだろう。", nil, nil, 0xfc6f0a61, 0x7b92d355, 0x4f913a29, nil, nil, "...mm" },
  [86792] = { "敵の兵力を削る", "Legashi Strongholdの外にいるKorsaのために、Legashi Hellraisersを$N1体、Legashi Soulstealersを$N2体、Legashi Blackguardsを$N3体倒してください。", "Legashiの拠点にいるsatyrは、外の野営地の連中よりもさらに恐ろしい。我々の隊は見つかり、たちまち圧倒されてしまった。\n\n一人は殺され、もう一人は捕らえられた。うまく退却できたのは私だけだ。恥じてうなだれたままRageroarのもとへ戻るわけにはいかないが、一人でLegashiと戦うこともできない。\n\nだから、satyrの軍勢を弱めるのを手伝ってほしい。奴らの拠点へ乗り込み、奴らを倒してくれ。", nil, nil, 0x3006e447, 0x72b75099, 0x81a0d931, nil, nil, "...mm" },
  [86796] = { "またな、Satyr", "GraalがLegashi Strongholdから脱出するのを手助けし、Legashi Strongholdの外にいるKorsaに知らせてください。", "そこの{race}！\n\nこの悪鬼どもが私の偵察隊を待ち伏せし、私を捕虜にした。奴らが私をどうするつもりか知らないが、知りたくもない。ここを脱出してUrsolanへ戻らねばならない。きっとKorsaが私のことを心配しているだろう。\n\nこの檻を破って、satyrの死体を道しるべのように残しながら去りたいところだが、あいにく少々多勢に無勢なのだ。\n\nもしかすると、君もこの悪鬼どもへの憎しみを分かち合い、私の脱出を手伝ってくれるのではないか？", nil, nil, 0x917ab6c1, 0x3b139131, 0xa6cc9072, nil, nil, "...mm" },
  [86797] = { "Rageroarのもとへ帰還", "UrsolanにいるGatekeeper Rageroarのところへ戻ってください。", "Legashiの拠点が弱った今、我々は名誉を持ってUrsolanへ戻れる。\n\n私より先に行き、Gatekeeper Rageroarにここの状況を伝えてくれ。", nil, nil, 0xd0444286, 0x9a2b8840, 0x08fbf252, nil, nil, "...mm" },
  [86798] = { "Timbermawの援軍", "Timbermaw HoldにいるGorn One Eyeと話し、援軍を出してくれるよう頼んでください。", "satyrが弱った今こそ、反撃に打って出る時だ。Legashi Strongholdの司令官、Prince Halanoxが我々の標的となる。だが、正面から奴に立ち向かうには、まだ兵の数が足りない。\n\nLegashiに追い出されて以来、我々はTimbermaw Holdのfurbolgたちとの連絡を絶たれている。彼らに援軍を頼むこともできるが、それには使者が必要だ。君がその使者になってくれ、{name}。\n\nTimbermaw Holdへ行き、Gorn One Eyeという名のfurbolgを探してくれ。彼が我々に必要な兵を提供してくれるだろう。", nil, nil, 0xcff8f73c, 0x178d840b, 0x3d91a7c7, nil, nil, "...mm" },
  [86799] = { "忍び寄る汚染", "Furzeの病気について、Elder Bramblesnapと話してください。", "<Furzeは醜く、ひどい咳をする。>\n\n聞いてくれ、{race}。話す力もあまり残っていない。これまでに知ったどんな病とも違う病に冒されている。まるで血そのものが燃えているようで、自分の本質そのものが崩れていくようだ。ほとんど動けないし、助けを呼びに行くことなどなおさらできない。\n\n頼む、Elder Bramblesnapを探してくれ。彼女のテントはここからすぐ北西だ。彼女ならどうすればいいかわかるはずだ。", nil, nil, 0x627f275e, 0xa7fad159, 0xca0fc3a4, nil, nil, "...mm" },
  [86804] = { "意外な出所", "Legashi EncampmentでLegashi Firewaterを手に入れる方法を見つけてください。", "このような症状に苦しんでいるのはFurzeが最初ではありません。Legashiの我々への攻撃が始まって以来、多くのBlackmawが同じような病を患いました。そして誰もが最後には堕落に屈し、理性を失って破壊的になってしまったのです。\n\n私は治療法の研究を続けてきました。私の研究によれば、Legashi自身のfirewaterを変成させれば、治療薬が作れるかもしれません。ですが、私自身ではそれを手に入れられないのです。\n\nここから東にあるLegashiの野営地で、firewaterか、その醸造方法が見つかるかもしれません。そうしてくれれば大いに助かります。", nil, nil, 0x0ca7df42, 0x3c52e9a8, 0xf92b9f54, nil, nil, "...mm" },
  [86812] = { "変成されたチンキ", "Mosshoof CoursersかThunderhead Skystormersを弱らせてから、$N1体にSatyrweed Tinctureを使ってください。", "firewaterを、Legashiの堕落を解く鍵になると信じているチンキ剤に変成させました。Blackmawの苦しみを早く和らげたい気持ちはやまやまですが、まずは試さなければなりません。\n\nUrsolanの東で、多くのcoursersやskystormersがsatyrの堕落に苦しんでいるのを見ました。彼らを実験の対象にしましょう。\n\nさあ、この治療薬になるはずのものを冒された獣たちに試してください。チンキ剤を与える前に、獣を弱らせておく必要があります。そうすれば、あまり抵抗されずに投与できるでしょう。", nil, nil, 0x95f2a457, 0x91c222e4, 0x1d1dca1f, nil, nil, "...mm" },
  [86813] = { "万能薬の候補", "FurzeにBramblesnap's Panaceaを与えてください。", "言わせてください、{class}。こんなに前向きな気持ちになったのは久しぶりです。このチンキ剤こそ、広がり続けるsatyrの災いから我々を救う万能薬になるかもしれません。たとえ残りの生涯をこの野営地で過ごすことになっても、我々は強く、堕落とは無縁でいられるでしょう。\n\nFurzeのところへ行って、この万能薬を与えてください。彼はもう十分に苦しみました。何かわかったら、私のところへ報告しに戻ってきてください。", nil, nil, 0x0a3969d9, 0x9c6ff7d9, 0x16695db1, nil, nil, "...mm" },
  [86814] = { "Blackmawの反撃", "AzsharaのLegashi StrongholdにTimbermaw War Bannerを立ててください。Prince Halanoxを倒し、UrsolanにいるGatekeeper Rageroarに勝利を報告してください。", "すぐに援軍をUrsolanへ送ろう。\n\nこの旗を持っていけ。Halanoxと戦う準備ができたら、奴の悪魔召喚の円陣にこれを立てるのだ。そうすれば奴を挑発し、我らのウォリアーたちに攻撃の合図を送ることになる。\n\nHalanoxを倒したら、Gatekeeper Rageroarに知らせてくれ。", nil, nil, 0xe5c8f325, 0x74517799, 0x4d944136, nil, nil, "...mm" },
  [86925] = { "苦労と災難", "Legashi Encampmentのsatyrから、Legashi Firewater Recipeを手に入れてください。", "この大釜を使えば、Elder Bramblesnapが求めているfirewaterを醸造できそうだ。\n\n作り方さえわかればいいのだが。きっと、Legashi Encampmentにいるsatyrの誰かがレシピを持っているはずだ。", nil, nil, 0x038883e2, 0x9181f455, 0xdfc7d0df, nil, nil, "...mm" },
  [86926] = { "Felfireよ燃えろ、大釜よ煮え立て", "Satyrweedを$N1個とFel Moteを、Legashi EncampmentにあるLegashi Cauldronのところへ持って行ってください。", "レシピにはこう書かれている。\n\n地獄の芽を摘み取れ\n5束あれば事足りる\n悪魔の力の欠片と混ぜ合わせれば\n奴らの最期の時が訪れよう", nil, nil, 0xe3b11032, 0x1571c3bb, 0x0f8aa386, nil, nil, "...mm" },
  [86927] = { "火酒の運搬", "Legashi FirewaterをUrsolanにいるElder Bramblesnapのところへ持って行ってください。", "satyrweedとfel moteが煮えたぎる液体に落ちると、有毒なガスが立ちのぼる。\n\n鼻をつまんで素早くサンプルを取り、Elder Bramblesnapのもとへ持ち帰るのがよさそうだ。", nil, nil, 0xf78815ba, 0xbbb8183d, 0x6809f961, nil, nil, "...mm" },
})
